iterations.reply:
Including the http-client import may cause problems until the graph definition is actually updated.

- **Instantiation risk:** The host binds only the interfaces in the current `with` clause (`state-rw`). Until the graph release lands, a component that imports `aap:caps/http-client@0.1.0` may fail the capability check or fail to instantiate.
- **What `q` contains:** `PublishedDigest` has no text field, so I used the digest's `date` as the query, percent-encoded. If you meant the `considered` ids, change `enrichment_query`. That would send item ids to the metadata host.
- **Output unchanged:** The fetch uses `fetch`, not `get`, so a transport failure doesn't trap. Its result is ignored.
- **Recording rule:** Items are marked seen only when `published` is true, so items from an unpublished digest are reconsidered next run.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{published-digest, run-report};

    import aap:caps/state-rw@0.1.0;
    import aap:caps/http-client@0.1.0;

    export run: func(published: published-digest) -> run-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

struct Node;

const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len() * 3);
    for &b in input.as_bytes() {
        let unreserved = b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~');
        if unreserved {
            out.push(b as char);
        } else {
            out.push('%');
            out.push(HEX[(b >> 4) as usize] as char);
            out.push(HEX[(b & 0x0F) as usize] as char);
        }
    }
    out
}

fn enrichment_query(published: &PublishedDigest) -> String {
    published.date.clone()
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment fetch: performed on every call, result deliberately unused so
        // the node's output is unchanged. Transport failures are values, not traps.
        let url = format!("{}{}", ENRICH_BASE, percent_encode(&enrichment_query(&published)));
        let _ = http_client::fetch(&url);

        let mut recorded: u32 = 0;
        if published.published {
            let mut done: Vec<&str> = Vec::new();
            for id in published.considered.iter() {
                if id.is_empty() || done.contains(&id.as_str()) {
                    continue;
                }
                state_rw::put(id, &published.date);
                done.push(id.as_str());
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

